import { normalizeDueRange } from './due-date.js';
import { matchesSearch } from './search.js';
import { matchesTaskFilters } from './task-filters.js';
import { orderDirectoryTasks } from './directory-order.js';

const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = element('p', '', { role: 'alert' });
    app.append(alert);
  }
  alert.textContent = message;
}

function searchForm(id, label, buttonLabel, onSearch) {
  const form = element('form', '', { class: 'search-form' });
  const input = element('input', '', { id, type: 'text' });
  form.append(element('label', label, { for: id }), input,
    element('button', buttonLabel, { type: 'submit' }));
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const query = input.value.trim();
    input.value = query;
    onSearch(query);
  });
  return form;
}

function dueRangeControls(onApply) {
  const dueRangeForm = element('form', '', { class: 'due-range' });
  const dueFrom = element('input', '', { id: 'due-from', type: 'text', placeholder: 'YYYY-MM-DD' });
  const dueThrough = element('input', '', { id: 'due-through', type: 'text', placeholder: 'YYYY-MM-DD' });
  dueRangeForm.append(element('label', 'Due from', { for: 'due-from' }), dueFrom,
    element('label', 'Due through', { for: 'due-through' }), dueThrough,
    element('button', 'Apply due range', { type: 'submit' }));
  dueRangeForm.addEventListener('submit', (event) => {
    event.preventDefault();
    const range = normalizeDueRange(dueFrom.value, dueThrough.value);
    if (range.error) return showError(range.error);
    dueFrom.value = range.from;
    dueThrough.value = range.through;
    app.querySelector('[role="alert"]')?.remove();
    onApply(range);
  });
  return dueRangeForm;
}

function filterSelect(id, label, options, controls, onChange) {
  const select = element('select', '', { id });
  for (const option of options) select.append(element('option', option, { value: option }));
  select.addEventListener('change', onChange);
  controls.append(element('label', label, { for: id }), select);
  return select;
}

async function showDirectory() {
  const back = element('button', 'Projects', { type: 'button' });
  back.addEventListener('click', () => { window.location.href = '/'; });
  app.replaceChildren(back, element('h1', 'Task directory'));
  document.title = 'Task directory · Workboard';
  let tasks = [];
  let dueRange = { from: '', through: '' };
  let query = '';
  let loading = true;
  const controls = element('div', '', { class: 'task-filters' });
  const scope = filterSelect('project-scope', 'Project scope', ['Active', 'Archived'], controls, render);
  const completion = filterSelect('task-filter', 'Task filter', ['All', 'Open', 'Completed', 'Deleted'], controls, render);
  const priority = filterSelect('priority-filter', 'Priority filter', ['All', 'Low', 'Normal', 'High'], controls, render);
  const order = filterSelect('directory-order', 'Directory order', ['Original', 'Priority', 'Due date', 'Title'], controls, render);
  const rangeForm = dueRangeControls((range) => { dueRange = range; render(); });
  const search = searchForm('directory-search', 'Directory search', 'Search directory', (value) => {
    query = value;
    render();
  });
  const list = element('ul', '', { class: 'directory-tasks', 'aria-label': 'Directory tasks' });
  const actions = element('div', '', { class: 'directory-actions' });
  const complete = element('button', 'Complete visible tasks', { type: 'button' });
  const reopen = element('button', 'Reopen visible tasks', { type: 'button' });
  complete.addEventListener('click', () => bulkCompletion(true));
  reopen.addEventListener('click', () => bulkCompletion(false));
  actions.append(complete, reopen);
  const summary = element('p', '', { 'data-testid': 'directory-summary' });
  const empty = element('p', 'No matching tasks', { role: 'status' });
  app.append(controls, rangeForm, search, actions, summary, list);

  function visibleTasks() {
    return tasks.filter((task) => task.archived === (scope.value === 'Archived')
      && matchesTaskFilters(task, completion.value, priority.value, dueRange, query));
  }

  async function bulkCompletion(completed) {
    if ((completed ? complete : reopen).disabled) return;
    loading = true;
    app.setAttribute('aria-busy', 'true');
    render();
    try {
      tasks = await request('/api/task-directory/completion', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ completed, scope: scope.value, completion: completion.value,
          priority: priority.value, dueRange, query }),
      });
      app.querySelector('[role="alert"]')?.remove();
    } catch (error) {
      showError(error.message);
    } finally {
      loading = false;
      app.setAttribute('aria-busy', 'false');
      render();
    }
  }

  function render() {
    const visible = orderDirectoryTasks(visibleTasks(), order.value);
    summary.hidden = loading;
    if (!loading) {
      const completedCount = visible.filter((task) => task.completed).length;
      summary.textContent = `${completedCount}/${visible.length} completed`;
    }
    const readOnly = loading || scope.value === 'Archived' || completion.value === 'Deleted';
    complete.disabled = readOnly || !visible.some((task) => !task.completed);
